public void testContainsKey() {
  final Map<K, V> map;
  final K unmappedKey;
  try {
    map = makePopulatedMap();
    unmappedKey = getKeyNotInPopulatedMap();
  } catch (UnsupportedOperationException e) {
    return;
  }
  assertFalse(map.containsKey(unmappedKey));
  try {
    assertFalse(map.containsKey(new IncompatibleKeyType()));
  } catch (ClassCastException e) {
    // Handle ClassCastException if key type is incompatible
  }
  try {
    assertTrue(map.containsKey(map.keySet().iterator().next()));
  } catch (NoSuchElementException e) {
    // Handle NoSuchElementException if map.keySet() is empty
  }
  if (allowsNullKeys) {
    map.containsKey(null);
  } else {
    try {
      map.containsKey(null);
    } catch (NullPointerException optional) {
    }
  }
  assertInvariants(map);
}
